1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's {@code checkDigit}: the single Luhn check digit (0..9) computed over
7	 * the digits contained in {@code customerCode}. Non-digit characters (the '-' separators)
8	 * are ignored. Kept out of {@link OwnerMapper} so MapStruct does not mistake the helper for
9	 * an implicit mapping method.
10	 */
11	public final class CheckDigit {
12	
13	    private CheckDigit() {
14	    }
15	
16	    /** The Luhn check digit (0..9) over the digits of {@code owner}'s customerCode. */
17	    public static int of(Owner owner) {
18	        return luhn(owner.getCustomerCode());
19	    }
20	
21	    /** Luhn check digit (0..9) over the digits contained in {@code value}. */
22	    private static int luhn(String value) {
23	        if (value == null) {
24	            return 0;
25	        }
26	        int sum = 0;
27	        boolean doubleDigit = true;
28	        for (int i = value.length() - 1; i >= 0; i--) {
29	            char c = value.charAt(i);
30	            if (c < '0' || c > '9') {
31	                continue;
32	            }
33	            int d = c - '0';
34	            if (doubleDigit) {
35	                d *= 2;
36	                if (d > 9) {
37	                    d -= 9;
38	                }
39	            }
40	            sum += d;
41	            doubleDigit = !doubleDigit;
42	        }
43	        return (10 - (sum % 10)) % 10;
44	    }
45	}
