1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's {@code identityKey}: the single duplicate-detection key that all owner
12	 * duplicate rules are now expressed through. The key is the 64-character SHA-256 hex digest of
13	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the telephone
14	 * is the stored (already E.164-normalized) value, the email is lower-cased or an empty segment
15	 * when absent, and {@code soundex(lastName)} is the American Soundex code of the last name (see
16	 * {@link Soundex}).
17	 *
18	 * <p>Two owners are duplicates only when their <em>whole</em> identityKey is equal: because the
19	 * telephone is part of the key, two owners with the same last name (hence the same soundex) and
20	 * postcode but <em>different</em> telephones have different keys and are both allowed — the
21	 * second is flagged a soft match, not rejected. Kept out of {@link OwnerMapper} so MapStruct does
22	 * not mistake the helper for an implicit mapping method.
23	 */
24	public final class IdentityKey {
25	
26	    private IdentityKey() {
27	    }
28	
29	    /** The duplicate-detection identity key for {@code owner}: SHA-256 hex over
30	     *  {@code normalizedTelephone|lowerEmail|soundex(lastName)}. */
31	    public static String of(Owner owner) {
32	        String raw = segment(owner.getTelephone()) + "|" + email(owner.getEmail()) + "|"
33	                + Soundex.of(owner.getLastName());
34	        return sha256Hex(raw);
35	    }
36	
37	    private static String sha256Hex(String value) {
38	        try {
39	            byte[] digest = MessageDigest.getInstance("SHA-256")
40	                    .digest(value.getBytes(StandardCharsets.UTF_8));
41	            StringBuilder sb = new StringBuilder(digest.length * 2);
42	            for (byte b : digest) {
43	                sb.append(String.format("%02x", b));
44	            }
45	            return sb.toString();
46	        }
47	        catch (NoSuchAlgorithmException e) {
48	            throw new IllegalStateException("SHA-256 not available", e);
49	        }
50	    }
51	
52	    private static String segment(String value) {
53	        return value == null ? "" : value;
54	    }
55	
56	    private static String email(String value) {
57	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
58	    }
59	}
