1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Puts date-derived values on a fiscal-year basis. The fiscal year starts on 1 July, so a date in
10	 * July or later belongs to the fiscal year ending the following calendar year; a date in January to
11	 * June belongs to the fiscal year ending in its own calendar year. Fiscal years are labelled
12	 * {@code 'FY<YY>'} after that ending year (e.g. 15 June 2026 and 1 July 2025 are both in 'FY26').
13	 *
14	 * <p>{@link #labelOf(Owner)} yields the label for an owner's business-day-adjusted
15	 * {@code registrationDate}; {@link #elapsedSince(LocalDate, LocalDate)} counts whole fiscal years
16	 * between two dates. Kept out of {@link OwnerMapper} so MapStruct does not mistake the helper for an
17	 * implicit mapping method.
18	 */
19	public final class FiscalYear {
20	
21	    /** The month a fiscal year starts on. */
22	    private static final Month FISCAL_YEAR_START = Month.JULY;
23	
24	    private FiscalYear() {
25	    }
26	
27	    /** The calendar year the fiscal year containing {@code date} ends in. */
28	    public static int endYearOf(LocalDate date) {
29	        return date.getMonthValue() >= FISCAL_YEAR_START.getValue() ? date.getYear() + 1 : date.getYear();
30	    }
31	
32	    /** The {@code 'FY<YY>'} label for {@code date}, YY being the last two digits of its fiscal year. */
33	    public static String labelOf(LocalDate date) {
34	        return String.format("FY%02d", endYearOf(date) % 100);
35	    }
36	
37	    /** The {@code 'FY<YY>'} label for an owner's registrationDate, or {@code null} when absent. */
38	    public static String labelOf(Owner owner) {
39	        LocalDate registrationDate = owner.getRegistrationDate();
40	        return registrationDate != null ? labelOf(registrationDate) : null;
41	    }
42	
43	    /** The number of whole fiscal years elapsed from {@code from} to {@code to}. */
44	    public static int elapsedSince(LocalDate from, LocalDate to) {
45	        return endYearOf(to) - endYearOf(from);
46	    }
47	}
