1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Set;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's marketing segment, formatted {@code '<TIER>_<AREA>'} — one of
9	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
10	 * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when the owner's {@code membershipLevel}
11	 * (see {@link Membership}) is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the
12	 * owner's {@link Locality} is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}. Kept out
13	 * of {@link OwnerMapper} so MapStruct does not mistake the helper for an implicit mapping method.
14	 */
15	public final class OwnerSegment {
16	
17	    /** The membership level (inclusive) at and above which an owner is {@code PREMIUM}. */
18	    private static final int PREMIUM_LEVEL = 3;
19	
20	    /** Localities counted as {@code METRO}; anything else is {@code REGIONAL}. */
21	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
22	
23	    private OwnerSegment() {
24	    }
25	
26	    /** The {@code '<TIER>_<AREA>'} segment for {@code owner}. */
27	    public static String of(Owner owner) {
28	        int level = owner.getMembershipLevel() != null ? owner.getMembershipLevel()
29	            : Membership.levelOf(owner);
30	        String tier = level >= PREMIUM_LEVEL ? "PREMIUM" : "STANDARD";
31	        String area = METRO_REGIONS.contains(Locality.of(owner)) ? "METRO" : "REGIONAL";
32	        return tier + "_" + area;
33	    }
34	}
