1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	import java.time.LocalDate;
6	
7	/**
8	 * Derives an owner's loyalty standing from a points system. {@link #pointsOf(Owner)} starts at 0
9	 * and adds 2 when an email is present, 1 when {@code namesakeCount} is 0, 2 for a household of 3 or
10	 * more (see {@code householdSize}), and 3 for a tenure of more than one elapsed fiscal year (see
11	 * {@link FiscalYear}). {@link #levelOf(Owner)} maps
12	 * those points to a numeric {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4
13	 * for 6 or more. Because a newly created owner has zero tenure, a new owner reaches at most 5
14	 * points and so never exceeds level 3. Kept out of {@link OwnerMapper} so MapStruct does not
15	 * mistake the helper for an implicit mapping method.
16	 */
17	public final class Membership {
18	
19	    /** Points added when the owner has a non-blank email. */
20	    private static final int POINTS_EMAIL = 2;
21	
22	    /** Points added when the owner's name is unique ({@code namesakeCount} is 0). */
23	    private static final int POINTS_UNIQUE_NAME = 1;
24	
25	    /** Points added when the owner belongs to a household of this size or larger. */
26	    private static final int POINTS_LARGE_HOUSEHOLD = 2;
27	
28	    /** The household size (members, inclusive) at which the household factor applies. */
29	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
30	
31	    /** Points added when the owner's tenure exceeds {@link #TENURE_FISCAL_YEARS_FOR_POINTS}. */
32	    private static final int POINTS_TENURE = 3;
33	
34	    /** A tenure of strictly more than this many elapsed fiscal years earns the tenure points. */
35	    private static final int TENURE_FISCAL_YEARS_FOR_POINTS = 1;
36	
37	    private Membership() {
38	    }
39	
40	    /** The loyalty points for {@code owner}. */
41	    public static int pointsOf(Owner owner) {
42	        int points = 0;
43	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
44	            points += POINTS_EMAIL;
45	        }
46	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
47	            points += POINTS_UNIQUE_NAME;
48	        }
49	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= LARGE_HOUSEHOLD_SIZE) {
50	            points += POINTS_LARGE_HOUSEHOLD;
51	        }
52	        LocalDate registrationDate = owner.getRegistrationDate();
53	        if (registrationDate != null
54	                && FiscalYear.elapsedSince(registrationDate, LocalDate.now()) > TENURE_FISCAL_YEARS_FOR_POINTS) {
55	            points += POINTS_TENURE;
56	        }
57	        return points;
58	    }
59	
60	    /** The numeric membership level (1..4) for {@code owner}, mapped from {@link #pointsOf(Owner)}. */
61	    public static int levelOf(Owner owner) {
62	        int points = pointsOf(owner);
63	        if (points >= 6) {
64	            return 4;
65	        }
66	        if (points >= 4) {
67	            return 3;
68	        }
69	        if (points >= 2) {
70	            return 2;
71	        }
72	        return 1;
73	    }
74	}
