1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's {@code timezone}: the IANA name for the owner's locality/region via the fixed
9	 * region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane).
10	 * The region is read from {@link Locality}, so timezone always agrees with the reported locality.
11	 * Returns {@code null} when the region resolves to no table entry (e.g. "UNKNOWN"). Kept out of
12	 * {@link OwnerMapper} so MapStruct does not mistake the helper for an implicit mapping method.
13	 */
14	public final class Timezone {
15	
16	    /** Region -> IANA timezone; anything not listed derives no timezone. */
17	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
18	        "NSW", "Australia/Sydney",
19	        "VIC", "Australia/Melbourne",
20	        "QLD", "Australia/Brisbane");
21	
22	    private Timezone() {
23	    }
24	
25	    /** The IANA timezone for {@code owner}, or {@code null} when its region has no table entry. */
26	    public static String of(Owner owner) {
27	        return REGION_TIMEZONE.get(Locality.of(owner));
28	    }
29	}
