1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.mapper.Locality;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}: REGION is the
16	 * canonical region derived from the owner's postcode (via {@link Locality}, falling back to the
17	 * city table, and {@code "UNKNOWN"} when neither resolves), and HASH8 is the first eight
18	 * upper-case hex characters of SHA-256 over the normalized telephone concatenated with the last
19	 * name (e.g. {@code 'NSW-1A2B3C4D'}). The identity is content-derived and carries no sequence
20	 * number, so it is stable and independent of creation order.
21	 *
22	 * <p>When the computed {@code '<REGION>-<HASH8>'} collides with an existing owner's customerCode,
23	 * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that makes it unique, so the
24	 * stored customerCode is always de-duplicated.
25	 *
26	 * <p>Runs after {@link NormalizeOwnerTelephone} (so the telephone is already E.164) and
27	 * {@link BuildOwner} (so the entity, hence its city, postcode and last name, exists), and before
28	 * {@link SaveOwner} (so the new owner is not yet among {@code findAll()}); it mutates the built
29	 * {@link Owner} in place. Every value built from the customerCode — the membership number and its
30	 * Luhn check digit, the create audit record, and the derived locality — therefore reflects this
31	 * region-and-hash identity.
32	 */
33	public class AssignCustomerCode {
34	
35	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
36	        String region = Locality.of(owner.getCity(), owner.getPostcode());
37	        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
38	        String base = region + "-" + hash8;
39	
40	        Set<String> existing = new HashSet<>();
41	        for (Owner other : ownerRepository.findAll()) {
42	            if (other.getCustomerCode() != null) {
43	                existing.add(other.getCustomerCode());
44	            }
45	        }
46	
47	        String customerCode = base;
48	        for (int n = 2; existing.contains(customerCode); n++) {
49	            customerCode = base + "-" + n;
50	        }
51	        owner.setCustomerCode(customerCode);
52	    }
53	
54	    /** First eight upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
55	    private static String hash8(String value) {
56	        try {
57	            byte[] digest = MessageDigest.getInstance("SHA-256")
58	                    .digest(value.getBytes(StandardCharsets.UTF_8));
59	            StringBuilder sb = new StringBuilder(digest.length * 2);
60	            for (byte b : digest) {
61	                sb.append(String.format("%02x", b));
62	            }
63	            return sb.substring(0, 8).toUpperCase();
64	        }
65	        catch (NoSuchAlgorithmException e) {
66	            throw new IllegalStateException("SHA-256 not available", e);
67	        }
68	    }
69	}
