1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.IdentityKey;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Rejects a create-owner request that duplicates an existing owner. Duplicate detection is now the
11	 * single identity key: the derived {@code identityKey} — the SHA-256 hex over
12	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
13	 * {@link IdentityKey}) — exactly equals an existing (non-deleted) owner's. This one rule expresses
14	 * what were the separate telephone and email duplicate checks.
15	 *
16	 * <p>Because the telephone is part of the key, two owners with the same last name and postcode but
17	 * different telephones no longer collide here: they are a soft match handled by
18	 * {@link CheckPossibleDuplicate}, not a 409. The former household-duplicate block (keyed on the
19	 * computed {@code householdId}) no longer applies.
20	 *
21	 * <p>The email-domain blocklist has already run earlier in the pipeline (see
22	 * {@link CheckEmailDomainAllowed}), so a blocked-domain request never reaches this step.
23	 *
24	 * <p>Runs before {@link CheckPossibleDuplicate}/{@link SaveOwner} (so the new owner is not yet
25	 * among {@code findAll()}). On a match raises {@link DuplicateIdentityException} (409).
26	 */
27	public class CheckOwnerIdentityUnique {
28	
29	    public void service(@Val Owner built, OwnerRepository ownerRepository)
30	            throws DuplicateIdentityException {
31	        String identityKey = IdentityKey.of(built);
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (Boolean.TRUE.equals(existing.getDeleted())) {
34	                continue; // a soft-deleted owner no longer blocks a duplicate
35	            }
36	            if (identityKey.equals(IdentityKey.of(existing))) {
37	                throw new DuplicateIdentityException(identityKey);
38	            }
39	        }
40	    }
41	}
