10	/**
11	 * Emits an audit line to the dedicated {@code AUDIT} logger on successful create,
12	 * carrying the newly-assigned owner id, its {@code customerCode}, its
13	 * {@code registrationDate}, its numeric {@code membershipLevel} and its
14	 * {@code membershipNumber}. Runs after {@link SaveOwner} (so the id exists) and
15	 * before {@link RespondWithOwnerCreated}.
16	 */
17	public class AuditOwnerCreated {
