19	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
20	
21	    public void service(@Val Owner owner) {
22	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
23	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
24	                Membership.levelOf(owner), owner.getMembershipNumber());
