6	/**
7	 * Immutable structured record of a successful owner create, serialized to the {@code AUDIT} logger
8	 * as the JSON object {@code {seq, ownerId, primaryIdentifier, membershipLevel, event}} with
9	 * {@code event} fixed to {@code "OWNER_CREATED"}.
10	 *
11	 * <p>{@code primaryIdentifier} carries the owner's <em>current</em> primary identifier, whatever
12	 * that happens to be. Today that is the {@code customerCode} (so the JSON key is
13	 * {@code "customerCode"}); when the customer code is later unified into the {@code memberId}, only
14	 * {@link #from(long, Owner)} and {@link #IDENTIFIER_FIELD} change and the event automatically
15	 * carries the {@code memberId} instead. Every field is captured at construction, so a published
16	 * event never changes.
17	 */
18	public record OwnerCreatedEvent(long seq, int ownerId, String primaryIdentifier, int membershipLevel) {
19	
20	    /** The one event type this record represents. */
21	    public static final String EVENT = "OWNER_CREATED";
22	
23	    /** JSON key for {@link #primaryIdentifier()} — tracks the current primary identifier's name. */
24	    private static final String IDENTIFIER_FIELD = "customerCode";
25	
26	    /**
27	     * Captures the event for a just-saved {@code owner} at sequence {@code seq}, reading the owner's
28	     * current primary identifier and membership level from a single place so future identifier
29	     * changes flow through here.
30	     */
31	    public static OwnerCreatedEvent from(long seq, Owner owner) {
32	        return new OwnerCreatedEvent(seq, owner.getId(), owner.getCustomerCode(), Membership.levelOf(owner));
33	    }
34	
35	    /** This event as a compact JSON object with the fields in specification order. */
36	    public String toJson() {
37	        return "{"
38	                + "\"seq\":" + this.seq
39	                + ",\"ownerId\":" + this.ownerId
40	                + ",\"" + IDENTIFIER_FIELD + "\":" + quote(this.primaryIdentifier)
41	                + ",\"membershipLevel\":" + this.membershipLevel
42	                + ",\"event\":" + quote(EVENT)
43	                + "}";
44	    }
45	
46	    /** Renders {@code value} as a JSON string literal, or {@code null} when absent. */
47	    private static String quote(String value) {
48	        if (value == null) {
49	            return "null";
50	        }
51	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
52	        for (int i = 0; i < value.length(); i++) {
53	            char c = value.charAt(i);
54	            switch (c) {
55	                case '"' -> sb.append("\\\"");
56	                case '\\' -> sb.append("\\\\");
57	                case '\n' -> sb.append("\\n");
58	                case '\r' -> sb.append("\\r");
59	                case '\t' -> sb.append("\\t");
60	                default -> sb.append(c);
61	            }
62	        }
63	        return sb.append('"').toString();
64	    }
65	}
